"""
views/empty_view.py — placeholder shown in the content pane
when no VM has been selected yet.
"""

import gi
gi.require_version("Gtk", "4.0")
gi.require_version("Adw", "1")

from gi.repository import Gtk, Adw


class EmptyView(Gtk.Box):
    def __init__(self):
        super().__init__(orientation=Gtk.Orientation.VERTICAL)

        # Header bar
        header = Adw.HeaderBar()
        header.set_show_end_title_buttons(True)
        self.append(header)

        # Centred status page
        status = Adw.StatusPage()
        status.set_icon_name("security-high-symbolic")
        status.set_title("BulwarkOS")
        status.set_description("Select a VM from the sidebar to view its controls and status.")
        status.set_vexpand(True)
        self.append(status)
